#!/usr/bin/env python3
"""Patch the macOS project generated by `flutter create --platforms macos .`:
app name, network entitlement (the sandbox blocks networking otherwise), plain-HTTP servers."""
import pathlib
import plistlib
import re
import sys

root = pathlib.Path(__file__).resolve().parent.parent
mac = root / "macos"
if not mac.exists():
    sys.exit("macos/ not found — run `flutter create --platforms macos .` first")

cfg = mac / "Runner/Configs/AppInfo.xcconfig"
s = cfg.read_text()
s = re.sub(r"^PRODUCT_NAME = .*$", "PRODUCT_NAME = Delos", s, flags=re.M)
cfg.write_text(s)

for name in ("DebugProfile.entitlements", "Release.entitlements"):
    f = mac / "Runner" / name
    with f.open("rb") as fh:
        p = plistlib.load(fh)
    p["com.apple.security.network.client"] = True
    with f.open("wb") as fh:
        plistlib.dump(p, fh)

info = mac / "Runner/Info.plist"
with info.open("rb") as fh:
    p = plistlib.load(fh)
p["NSAppTransportSecurity"] = {"NSAllowsArbitraryLoads": True}
p["LSApplicationCategoryType"] = "public.app-category.video"
with info.open("wb") as fh:
    plistlib.dump(p, fh)

win = mac / "Runner/MainFlutterWindow.swift"
if win.exists():
    s = win.read_text()
    if "setContentSize" not in s:
        s = s.replace("self.contentViewController = flutterViewController",
                      "self.contentViewController = flutterViewController\n"
                      "    self.setContentSize(NSSize(width: 1280, height: 760))\n"
                      "    self.center()")
        win.write_text(s)
print("patched macOS project")

test = root / "test/widget_test.dart"
if test.exists():
    test.unlink()
